from typing import List
import sys

def lenOfVDiagonal(grid: List[List[int]]) -> int:
    if not grid or not grid[0]:
        return 0

    n, m = len(grid), len(grid[0])
    sys.setrecursionlimit(2000000)

    def get_next(val):
        return 2 if val == 1 or val == 0 else 0

    # Directions: (dr, dc)
    # 0: Down-Right (+1, +1), 1: Down-Left (+1, -1), 
    # 2: Up-Left (-1, -1), 3: Up-Right (-1, +1)
    dirs = [(1, 1), (1, -1), (-1, -1), (-1, 1)]

    memo = {}

    def get_dist(r, c, d):
        if (r, c, d) in memo:
            return memo[(r, c, d)]
        dr, dc = dirs[d]
        nr, nc = r + dr, c + dc
        res = 1
        if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == get_next(grid[r][c]):
            res = 1 + get_dist(nr, nc, d)
        memo[(r, c, d)] = res
        return res

    # Precompute all straight distances for the sequence 2,0,2,0... or 0,2,0,2...
    for r in range(n):
        for c in range(m):
            for d in range(4):
                get_dist(r, c, d)

    ans = 0
    for r in range(n):
        for c in range(m):
            if grid[r][c] == 1:
                ans = max(ans, 1)
                for d in range(4):
                    dr, dc = dirs[d]
                    path = [(r, c)]
                    curr_r, curr_c = r + dr, c + dc

                    # Build the initial straight diagonal path starting with '1' then '2', '0'...
                    while 0 <= curr_r < n and 0 <= curr_c < m and grid[curr_r][curr_c] == get_next(grid[path[-1][0]][path[-1][1]]):
                        path.append((curr_r, curr_c))
                        curr_r += dr
                        curr_c += dc

                    # For each cell in the path p_i, consider turning clockwise at that cell
                    for i in range(len(path)):
                        pr, pc = path[i]
                        # Turn is 90-degree clockwise: (d + 1) % 4
                        nd = (d + 1) % 4
                        ndr, ndc = dirs[nd]
                        nr, nc = pr + ndr, pc + ndc

                        if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == get_next(grid[pr][pc]):
                            # Length is steps taken in first direction (i+1) + length from turn point
                            ans = max(ans, (i + 1) + get_dist(nr, nc, nd))
                        else:
                            # If no turn possible, the path ends at p_i
                            ans = max(ans, i + 1)

    return ans

