def maxScore(a: List[int], b: List[int]) -> int:
    # DP table to store the max score for each prefix of a
    # dp[j] represents the max score using first j elements of a
    dp = [-float('inf')] * 5
    dp[0] = 0

    for x in b:
        # Iterate backwards to update DP states based on previous results
        for i in range(3, -1, -1):
            if dp[i] != -float('inf'):
                dp[i+1] = max(dp[i+1], dp[i] + a[i] * x)

    return int(dp[4])
