import collections

def makeStringGood(s: str) -> int:
    counts = [0] * 26
    for char in s:
        counts[ord(char) - ord('a')] += 1

    n = len(s)
    min_ops = float('inf')

    # Try all possible target counts K and number of distinct characters m
    for K in range(1, n + 1):
        # Optimization: Only check m that could realistically produce a good string.
        # Since s length is up to 20,000, and we need at least 3 chars for the problem constraints
        # but let's just iterate all possible m from 1 to 26.
        for m in range(1, 27):
            total_needed = K * m
            if total_needed == 0: continue

            # Cost calculation logic:
            # Each character in the original string s is either:
            #  - Kept at position p_j (cost 0). Saving = 2 relative to delete+insert.
            #  - Moved one step forward from i to p_j=i+1 (cost 1). Saving = 1 relative to delete+insert.
            #  - Deleted or Inserted (cost 1 each, total 2 for a replacement). Saving = 0.
            # Total Cost = n + m*K - Sum(Savings)
            # Where Savings = sum over j=1..m of (2 * s_2j + 1 * s_1j)
            # s_2j is count of chars at p_j used for free.
            # s_1j is count of chars moved from p_j-1 to p_j.

            # dp[j] = {type: max_savings} 
            # type 0: i-1 was not in P, type 1: i-1 was in P
            dp = [{} for _ in range(m + 1)]
            dp[0][None] = 0

            for i in range(26):
                new_dp = [{} for _ in range(m + 1)]
                c = counts[i]
                for j in range(m + 1):
                    for prev_type, current_savings in dp[j].items():
                        # Option 1: Position i is NOT in P
                        if new_dp[j].get(0, -1) < current_savings:
                            new_dp[j][0] = current_savings

                        # Option 2: Position i IS in P
                        if j + 1 <= m:
                            s2 = min(K, c)
                            rem = K - s2
                            s1 = 0
                            if prev_type == 0: # i-1 was not in P, leftover is counts[i-1]
                                if i > 0:
                                    s1 = min(rem, counts[i-1])
                            elif prev_type == 1: # i-1 was in P, leftover is max(0, counts[i-1]-K)
                                if i > 0:
                                    s1 = min(rem, max(0, counts[i-1] - K))
                            else: # prev_type is None (first letter)
                                s1 = 0

                            new_savings = current_savings + 2 * s2 + s1
                            if new_dp[j+1].get(1, -1) < new_savings:
                                new_dp[j+1][1] = new_savings
                dp = new_dp

            max_s = -1
            for s_val in dp[m].values():
                if s_val > max_s:
                    max_s = s_val

            if max_s != -1:
                min_ops = min(min_ops, n + K * m - max_s)

    return int(min_ops)

